/** Third-party notices (plan 30): `thirdPartyLicenses.json` is generated by `npm run licenses`
 *  (scripts/licenses.mjs). These checks fail when a dependency was added without regenerating it,
 *  or when the generated data is inconsistent. */
import { readFileSync } from 'fs';
import { join } from 'path';
import {
  THIRD_PARTY_LICENSES,
  filterPackages,
  licenceSummary,
  packageKey,
  type LicenseData,
} from './licenses';

const root = join(__dirname, '..', '..', '..', '..');
const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')) as {
  dependencies: Record<string, string>;
  devDependencies: Record<string, string>;
};

describe('thirdPartyLicenses.json', () => {
  const d = THIRD_PARTY_LICENSES;

  it('lists every direct dependency of package.json (run `npm run licenses` after adding one)', () => {
    const listed = new Set(d.packages.map((p) => p.name));
    const missing = Object.keys(pkg.dependencies).filter((name) => !listed.has(name));
    expect(missing).toEqual([]);
    expect(d.direct).toEqual(Object.keys(pkg.dependencies).sort());
  });

  it('leaves out development-only tools', () => {
    const listed = new Set(d.packages.map((p) => p.name));
    for (const tool of ['jest', 'eslint', 'prettier', 'typescript', 'sharp']) {
      expect(Object.keys(pkg.devDependencies)).toContain(tool);
      expect(listed.has(tool)).toBe(false);
    }
  });

  it('every package declares a licence and every text reference resolves', () => {
    expect(d.packages.length).toBeGreaterThan(100);
    for (const p of d.packages) {
      expect({ name: p.name, license: p.license }).not.toEqual({
        name: p.name,
        license: 'UNKNOWN',
      });
      if (p.text) expect(typeof d.texts[p.text]).toBe('string');
    }
    const keys = d.packages.map(packageKey);
    expect(new Set(keys).size).toBe(keys.length);
  });

  it('carries the copyright notice of the main runtime packages', () => {
    const react = d.packages.find((p) => p.name === 'react');
    expect(react?.license).toBe('MIT');
    expect(react?.copyright.join(' ')).toMatch(/Meta Platforms|Facebook/);
    expect(react?.text && d.texts[react.text]).toMatch(/Permission is hereby granted/);
  });
});

describe('licence helpers', () => {
  const data: LicenseData = {
    schema: 'bolid.licenses.v1',
    app: 'x',
    direct: ['a'],
    packages: [
      {
        name: 'alpha',
        version: '1.0.0',
        license: 'MIT',
        repository: null,
        copyright: [],
        text: null,
      },
      {
        name: 'beta',
        version: '2.0.0',
        license: 'ISC',
        repository: null,
        copyright: [],
        text: null,
      },
      {
        name: 'gamma',
        version: '3.0.0',
        license: 'MIT',
        repository: null,
        copyright: [],
        text: null,
      },
    ],
    texts: {},
  };

  it('summarises by licence, most used first', () => {
    expect(licenceSummary(data)).toEqual([
      { license: 'MIT', count: 2 },
      { license: 'ISC', count: 1 },
    ]);
  });

  it('filters by name or licence, case-insensitively', () => {
    expect(filterPackages(data, '').map((p) => p.name)).toEqual(['alpha', 'beta', 'gamma']);
    expect(filterPackages(data, 'GAM').map((p) => p.name)).toEqual(['gamma']);
    expect(filterPackages(data, 'isc').map((p) => p.name)).toEqual(['beta']);
    expect(filterPackages(data, 'zzz')).toEqual([]);
  });
});
